.text
main:	add $14, $0, $0		#$14 - move para direita
	lui $15, 0xffff
	looptela:
	lui $8, 0x1001		#$8 - valor da UG atual
	addi $9, $8, 0x8000	#$9 - comeco da linha de data
	add $10, $14, $9	#$10 - valor do dado grafico atual
	addi $11, $0, 64	#$11 - contador de linhas
	gerartela:
