		add $10, $14, $9
		bne $11, $0, gerartela
	ficarparado:
	lw $16, 0($15)
	beq $16, $0, ficarparado
	lw $16, 4($15)
      	addi $17, $0, ' '
      	beq $16, $17, fim
	beq $14, 2988, ficarparado
      	addi $17, $0, 'd'
      	bne $16, $17, ficarparado
	addi $14, $14, 4
	j looptela
	fim:
	addi $2, $0, 10
	syscall